// ConfigurationHandler is an implementation of the elephant.distribution.Configuration service.
type ConfigurationHandler interface {
	// RegisterConfigGeneration registers a complete configuration set
	// (schemas + type configurations) as a new generation. Existing schema
	// versions can be re-used by name and version without re-supplying the
	// spec; if the spec is supplied for an existing version it must match
	// the stored one. Returns the new generation ID.
	RegisterConfigGeneration(context.Context, *connect.Request[distribution.RegisterConfigGenerationRequest]) (*connect.Response[distribution.RegisterConfigGenerationResponse], error)
	// ActivateConfigGeneration switches the active configuration to the
	// generation with the given ID.
	ActivateConfigGeneration(context.Context, *connect.Request[distribution.ActivateConfigGenerationRequest]) (*connect.Response[distribution.ActivateConfigGenerationResponse], error)
	// GetActiveConfigGeneration returns the currently active generation,
	// including its schemas and type configurations. Supports long polling
	// for changes.
	GetActiveConfigGeneration(context.Context, *connect.Request[distribution.GetActiveConfigGenerationRequest]) (*connect.Response[distribution.GetActiveConfigGenerationResponse], error)
	// ListConfigGenerations lists historical generations, most recent first.
	ListConfigGenerations(context.Context, *connect.Request[distribution.ListConfigGenerationsRequest]) (*connect.Response[distribution.ListConfigGenerationsResponse], error)
	// GetSchema retrieves a stored schema spec by name and version.
	GetSchema(context.Context, *connect.Request[distribution.GetSchemaRequest]) (*connect.Response[distribution.GetSchemaResponse], error)
	// GetAllActiveSchemas returns the schemas in the active generation.
	// Supports long polling so clients can watch for changes.
	GetAllActiveSchemas(context.Context, *connect.Request[distribution.GetAllActiveSchemasRequest]) (*connect.Response[distribution.GetAllActiveSchemasResponse], error)
	// GetDocumentTypes lists the document types declared by schemas in the
	// active generation.
	GetDocumentTypes(context.Context, *connect.Request[distribution.GetDocumentTypesRequest]) (*connect.Response[distribution.GetDocumentTypesResponse], error)
	// GetTypeConfiguration returns the configuration for a type in the
	// active generation.
	GetTypeConfiguration(context.Context, *connect.Request[distribution.GetTypeConfigurationRequest]) (*connect.Response[distribution.GetTypeConfigurationResponse], error)
	// SetRendererSecret stores the shared secret a remote HTML renderer
	// authenticates with. A renderer names its secret implicitly: the
	// renderer "factbox-special" uses the secret "factbox-special".
	//
	// The secret is write-only. It is stored encrypted under the delivery
	// keyring and there is no call that returns it; ListRendererSecrets
	// reports which secrets exist and when they were written, and nothing
	// else. An environment-provided secret takes precedence over a stored
	// one, so an emergency override does not need a write here.
	//
	// Store the secret before registering a generation that names the
	// renderer: registration resolves every remote renderer's secret and
	// refuses a generation whose secrets are not resolvable.
	SetRendererSecret(context.Context, *connect.Request[distribution.SetRendererSecretRequest]) (*connect.Response[distribution.SetRendererSecretResponse], error)
	// DeleteRendererSecret removes a stored renderer secret. It does not
	// invalidate a configuration generation that names the renderer: the
	// renderer is skipped at render time, its blocks fall back to the
	// built-in renderers, and the missing-secret gauge is raised.
	DeleteRendererSecret(context.Context, *connect.Request[distribution.DeleteRendererSecretRequest]) (*connect.Response[distribution.DeleteRendererSecretResponse], error)
	// ListRendererSecrets lists the stored renderer secrets by name, with
	// the keyring entry each one is sealed under and when it was last
	// written. Never their values.
	ListRendererSecrets(context.Context, *connect.Request[distribution.ListRendererSecretsRequest]) (*connect.Response[distribution.ListRendererSecretsResponse], error)
	// SetSyncState sets the desired state of the distribution sync worker.
	// A cold-started service (no configuration, no sync position) starts
	// out paused so that the repository eventlog isn't consumed - and
	// discarded - before a configuration generation has been activated.
	SetSyncState(context.Context, *connect.Request[distribution.SetSyncStateRequest]) (*connect.Response[distribution.SetSyncStateResponse], error)
	// GetSyncStatus returns the desired and current state of the
	// distribution sync worker together with its position in the
	// repository eventlog.
	GetSyncStatus(context.Context, *connect.Request[distribution.GetSyncStatusRequest]) (*connect.Response[distribution.GetSyncStatusResponse], error)
	// EraseDocument erases a document's content from every store we control:
	// the hot version rows, the archived objects, the search index copies,
	// the extracted delivery fields and the cached fragments. It never
	// touches the eventlog, whose entries carry identifiers and hashes only,
	// so the transparency log survives an erasure with its hash chain
	// intact.
	//
	// Erasure is point-in-time. It removes the content that exists when it
	// is ordered and does not blocklist the UUID: a document re-published
	// afterwards is a new document and is distributed and indexed normally.
	//
	// It also STOPS THE CONTENT GOING OUT and tells everybody who was given
	// it. Undelivered queue rows for the document are dropped, and every
	// destination that was ever pushed a copy is sent a deletion marker in
	// the same feed the content arrived in - the ordinary marker envelope,
	// at the next entry of that document's chain, saying "deleted". Nothing
	// is deleted at a destination: push is append-only, we do not control
	// what a customer retains, and a marker is the only honest instrument we
	// have.
	//
	// THIS CALL IS NOT THE ORDINARY TRIGGER. Deleting a document in the
	// repository erases it here: the delete event drives the same erasure
	// this RPC records, and an editorial delete inside becomes an erasure
	// outside. What the RPC is for is the content that trigger cannot reach
	// - a document deleted before distribution ingested delete events, and
	// content that exists here only as imported history with no live
	// repository document to delete. Calling it for a document that has
	// already been erased is a no-op and safe.
	//
	// The call is idempotent and returns the recorded request. A request is
	// complete once no archived index snapshot holds a copy any more, which
	// can require the affected partitions to be re-materialized, and once
	// every destination that was given a copy has been told - the marker
	// delivered, or the destination and its credentials gone. Use
	// GetErasureStatus to prove completion.
	//
	// What it has never covered, and cannot: content a customer has already
	// ingested from a destination into their own systems. We do not delete
	// files on a customer's machine and do not claim to.
	EraseDocument(context.Context, *connect.Request[distribution.EraseDocumentRequest]) (*connect.Response[distribution.EraseDocumentResponse], error)
	// GetErasureStatus returns the recorded erasure request for a document
	// and what it is still waiting for: the archived index partitions
	// awaiting re-materialization, and the delivery destinations that were
	// given a copy and have not been told.
	//
	// One narrow window sits outside the proof, and it is stated here rather
	// than left to a design document. An object whose write completed but
	// whose inventory row was never recorded - a process that died between
	// the two, or a lost acknowledgement from the recipient - is
	// indistinguishable from a file the customer put there themselves, so if
	// it is the only copy a destination ever received, that destination is
	// not on the list. The queue row survives, so the next pass re-sends and
	// records it; the exposure is one restart intersected with an erasure.
	GetErasureStatus(context.Context, *connect.Request[distribution.GetErasureStatusRequest]) (*connect.Response[distribution.GetErasureStatusResponse], error)
	// RematerializePartition orders an archived index partition to be
	// rebuilt from the archive: overlay corrections are folded in, deleted
	// and erased documents are left out, and the result is built with the
	// current mappings and schemas.
	//
	// The call records the order and returns; the rebuild itself runs in the
	// index tiering job, which owns the snapshot repository and the warm
	// tier. Call it again to see how far it has got - the response is the
	// recorded state either way, and ordering a rebuild that is already
	// under way changes nothing.
	//
	// A period of the form "yyyy" orders the rollup of a whole year: the
	// years quarter partitions are rebuilt into a single yearly one and
	// their mounts are dropped.
	RematerializePartition(context.Context, *connect.Request[distribution.RematerializePartitionRequest]) (*connect.Response[distribution.RematerializePartitionResponse], error)
	// CreateIndexGeneration registers a new index generation: a complete set
	// of search indexes with an index name prefix of its own, built on one of
	// the OpenSearch clusters the deployment declares.
	//
	// The generation is populated by the ordinary backfill - the indexer that
	// picks it up drains the archive and then tails the eventlog - while the
	// active generation keeps serving. Subscription matching is suppressed
	// for the whole build, so creating a generation never re-notifies a
	// subscription, but the percolator indexes are seeded as it goes, so
	// matching works from the moment it is activated.
	//
	// Use it to rebuild the index from scratch after a mapping change that
	// cannot be applied to live indexes, or to move the index to another
	// cluster - which is how an OpenSearch major version upgrade is done:
	// create a generation on the new cluster, watch it catch up with
	// ListIndexGenerations, compare results through the generation override
	// on Search.Query, activate, and delete the old one.
	CreateIndexGeneration(context.Context, *connect.Request[distribution.CreateIndexGenerationRequest]) (*connect.Response[distribution.CreateIndexGenerationResponse], error)
	// ListIndexGenerations lists the index generations together with the
	// position each one's indexer has reached in the distribution eventlog
	// and the current head of that log. That is the catch-up view a rebuild
	// is followed through: a candidate is ready to be activated once its lag
	// has come down to a handful of events.
	ListIndexGenerations(context.Context, *connect.Request[distribution.ListIndexGenerationsRequest]) (*connect.Response[distribution.ListIndexGenerationsResponse], error)
	// ActivateIndexGeneration makes a generation the one that search,
	// threshold calibration and subscription matching read. The switch is
	// atomic and exactly one generation is active at a time.
	//
	// Activation is refused when the candidate lags the head of the eventlog
	// by more than a small gate, ten events by default, because a generation
	// that is behind would answer with stale content the moment it took
	// over. It is refused on the same gate when the candidate stands that
	// far above the position the outgoing generation has matched up to,
	// since that distance is what the matching handover has to replay and an
	// outgoing generation that is stalled or disabled can be arbitrarily far
	// behind a candidate that is on the head. Force activates regardless,
	// which is the right call when the outgoing generation is unreachable
	// and the wrong one otherwise.
	//
	// Subscription matching is handed over rather than dropped. Activation
	// records the position the outgoing generation had matched up to and
	// stops its matching there; the incoming generation replays the events
	// from that position up to its own cursor for matching only. Match rows
	// are keyed on subscription and event, so replaying an event is
	// idempotent - but the two generations read the log in different pages,
	// and a document that occurs more than once in a page is matched under
	// the last event of that page, so the same document version can end up
	// recorded under two events. Delivery across a cutover is at-least-once
	// with the occasional duplicate: deduplicate on the subscription, the
	// document UUID and the version if that matters to you.
	ActivateIndexGeneration(context.Context, *connect.Request[distribution.ActivateIndexGenerationRequest]) (*connect.Response[distribution.ActivateIndexGenerationResponse], error)
	// DeleteIndexGeneration deletes an inactive generation. The active
	// generation cannot be deleted - activate another one first.
	//
	// The call records the deletion and returns; the cleanup runs
	// asynchronously and is scoped by the generation's index prefix: its
	// document, percolator and overlay indexes, the bookkeeping rows that
	// name them, its eventlog cursor, and the snapshots under the
	// generation's base path in the snapshot repository. Nothing outside the
	// prefix is touched, so deleting a generation can never take content
	// away from the one that is serving.
	DeleteIndexGeneration(context.Context, *connect.Request[distribution.DeleteIndexGenerationRequest]) (*connect.Response[distribution.DeleteIndexGenerationResponse], error)
}

// NewConfigurationHandler builds an HTTP handler from the service implementation. It returns the
// path on which to mount the handler and the handler itself.
//
// By default, handlers support the Connect, gRPC, and gRPC-Web protocols with the binary Protobuf
// and JSON codecs. They also support gzip compression.
func NewConfigurationHandler(svc ConfigurationHandler, opts ...connect.HandlerOption) (string, http.Handler) {
	configurationMethods := distribution.File_distribution_service_proto.Services().ByName("Configuration").Methods()
	configurationRegisterConfigGenerationHandler := connect.NewUnaryHandler(
		ConfigurationRegisterConfigGenerationProcedure,
		svc.RegisterConfigGeneration,
		connect.WithSchema(configurationMethods.ByName("RegisterConfigGeneration")),
		connect.WithHandlerOptions(opts...),
	)
	configurationActivateConfigGenerationHandler := connect.NewUnaryHandler(
		ConfigurationActivateConfigGenerationProcedure,
		svc.ActivateConfigGeneration,
		connect.WithSchema(configurationMethods.ByName("ActivateConfigGeneration")),
		connect.WithHandlerOptions(opts...),
	)
	configurationGetActiveConfigGenerationHandler := connect.NewUnaryHandler(
		ConfigurationGetActiveConfigGenerationProcedure,
		svc.GetActiveConfigGeneration,
		connect.WithSchema(configurationMethods.ByName("GetActiveConfigGeneration")),
		connect.WithHandlerOptions(opts...),
	)
	configurationListConfigGenerationsHandler := connect.NewUnaryHandler(
		ConfigurationListConfigGenerationsProcedure,
		svc.ListConfigGenerations,
		connect.WithSchema(configurationMethods.ByName("ListConfigGenerations")),
		connect.WithHandlerOptions(opts...),
	)
	configurationGetSchemaHandler := connect.NewUnaryHandler(
		ConfigurationGetSchemaProcedure,
		svc.GetSchema,
		connect.WithSchema(configurationMethods.ByName("GetSchema")),
		connect.WithHandlerOptions(opts...),
	)
	configurationGetAllActiveSchemasHandler := connect.NewUnaryHandler(
		ConfigurationGetAllActiveSchemasProcedure,
		svc.GetAllActiveSchemas,
		connect.WithSchema(configurationMethods.ByName("GetAllActiveSchemas")),
		connect.WithHandlerOptions(opts...),
	)
	configurationGetDocumentTypesHandler := connect.NewUnaryHandler(
		ConfigurationGetDocumentTypesProcedure,
		svc.GetDocumentTypes,
		connect.WithSchema(configurationMethods.ByName("GetDocumentTypes")),
		connect.WithHandlerOptions(opts...),
	)
	configurationGetTypeConfigurationHandler := connect.NewUnaryHandler(
		ConfigurationGetTypeConfigurationProcedure,
		svc.GetTypeConfiguration,
		connect.WithSchema(configurationMethods.ByName("GetTypeConfiguration")),
		connect.WithHandlerOptions(opts...),
	)
	configurationSetRendererSecretHandler := connect.NewUnaryHandler(
		ConfigurationSetRendererSecretProcedure,
		svc.SetRendererSecret,
		connect.WithSchema(configurationMethods.ByName("SetRendererSecret")),
		connect.WithHandlerOptions(opts...),
	)
	configurationDeleteRendererSecretHandler := connect.NewUnaryHandler(
		ConfigurationDeleteRendererSecretProcedure,
		svc.DeleteRendererSecret,
		connect.WithSchema(configurationMethods.ByName("DeleteRendererSecret")),
		connect.WithHandlerOptions(opts...),
	)
	configurationListRendererSecretsHandler := connect.NewUnaryHandler(
		ConfigurationListRendererSecretsProcedure,
		svc.ListRendererSecrets,
		connect.WithSchema(configurationMethods.ByName("ListRendererSecrets")),
		connect.WithHandlerOptions(opts...),
	)
	configurationSetSyncStateHandler := connect.NewUnaryHandler(
		ConfigurationSetSyncStateProcedure,
		svc.SetSyncState,
		connect.WithSchema(configurationMethods.ByName("SetSyncState")),
		connect.WithHandlerOptions(opts...),
	)
	configurationGetSyncStatusHandler := connect.NewUnaryHandler(
		ConfigurationGetSyncStatusProcedure,
		svc.GetSyncStatus,
		connect.WithSchema(configurationMethods.ByName("GetSyncStatus")),
		connect.WithHandlerOptions(opts...),
	)
	configurationEraseDocumentHandler := connect.NewUnaryHandler(
		ConfigurationEraseDocumentProcedure,
		svc.EraseDocument,
		connect.WithSchema(configurationMethods.ByName("EraseDocument")),
		connect.WithHandlerOptions(opts...),
	)
	configurationGetErasureStatusHandler := connect.NewUnaryHandler(
		ConfigurationGetErasureStatusProcedure,
		svc.GetErasureStatus,
		connect.WithSchema(configurationMethods.ByName("GetErasureStatus")),
		connect.WithHandlerOptions(opts...),
	)
	configurationRematerializePartitionHandler := connect.NewUnaryHandler(
		ConfigurationRematerializePartitionProcedure,
		svc.RematerializePartition,
		connect.WithSchema(configurationMethods.ByName("RematerializePartition")),
		connect.WithHandlerOptions(opts...),
	)
	configurationCreateIndexGenerationHandler := connect.NewUnaryHandler(
		ConfigurationCreateIndexGenerationProcedure,
		svc.CreateIndexGeneration,
		connect.WithSchema(configurationMethods.ByName("CreateIndexGeneration")),
		connect.WithHandlerOptions(opts...),
	)
	configurationListIndexGenerationsHandler := connect.NewUnaryHandler(
		ConfigurationListIndexGenerationsProcedure,
		svc.ListIndexGenerations,
		connect.WithSchema(configurationMethods.ByName("ListIndexGenerations")),
		connect.WithHandlerOptions(opts...),
	)
	configurationActivateIndexGenerationHandler := connect.NewUnaryHandler(
		ConfigurationActivateIndexGenerationProcedure,
		svc.ActivateIndexGeneration,
		connect.WithSchema(configurationMethods.ByName("ActivateIndexGeneration")),
		connect.WithHandlerOptions(opts...),
	)
	configurationDeleteIndexGenerationHandler := connect.NewUnaryHandler(
		ConfigurationDeleteIndexGenerationProcedure,
		svc.DeleteIndexGeneration,
		connect.WithSchema(configurationMethods.ByName("DeleteIndexGeneration")),
		connect.WithHandlerOptions(opts...),
	)
	return "/elephant.distribution.Configuration/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case ConfigurationRegisterConfigGenerationProcedure:
			configurationRegisterConfigGenerationHandler.ServeHTTP(w, r)
		case ConfigurationActivateConfigGenerationProcedure:
			configurationActivateConfigGenerationHandler.ServeHTTP(w, r)
		case ConfigurationGetActiveConfigGenerationProcedure:
			configurationGetActiveConfigGenerationHandler.ServeHTTP(w, r)
		case ConfigurationListConfigGenerationsProcedure:
			configurationListConfigGenerationsHandler.ServeHTTP(w, r)
		case ConfigurationGetSchemaProcedure:
			configurationGetSchemaHandler.ServeHTTP(w, r)
		case ConfigurationGetAllActiveSchemasProcedure:
			configurationGetAllActiveSchemasHandler.ServeHTTP(w, r)
		case ConfigurationGetDocumentTypesProcedure:
			configurationGetDocumentTypesHandler.ServeHTTP(w, r)
		case ConfigurationGetTypeConfigurationProcedure:
			configurationGetTypeConfigurationHandler.ServeHTTP(w, r)
		case ConfigurationSetRendererSecretProcedure:
			configurationSetRendererSecretHandler.ServeHTTP(w, r)
		case ConfigurationDeleteRendererSecretProcedure:
			configurationDeleteRendererSecretHandler.ServeHTTP(w, r)
		case ConfigurationListRendererSecretsProcedure:
			configurationListRendererSecretsHandler.ServeHTTP(w, r)
		case ConfigurationSetSyncStateProcedure:
			configurationSetSyncStateHandler.ServeHTTP(w, r)
		case ConfigurationGetSyncStatusProcedure:
			configurationGetSyncStatusHandler.ServeHTTP(w, r)
		case ConfigurationEraseDocumentProcedure:
			configurationEraseDocumentHandler.ServeHTTP(w, r)
		case ConfigurationGetErasureStatusProcedure:
			configurationGetErasureStatusHandler.ServeHTTP(w, r)
		case ConfigurationRematerializePartitionProcedure:
			configurationRematerializePartitionHandler.ServeHTTP(w, r)
		case ConfigurationCreateIndexGenerationProcedure:
			configurationCreateIndexGenerationHandler.ServeHTTP(w, r)
		case ConfigurationListIndexGenerationsProcedure:
			configurationListIndexGenerationsHandler.ServeHTTP(w, r)
		case ConfigurationActivateIndexGenerationProcedure:
			configurationActivateIndexGenerationHandler.ServeHTTP(w, r)
		case ConfigurationDeleteIndexGenerationProcedure:
			configurationDeleteIndexGenerationHandler.ServeHTTP(w, r)
		default:
			http.NotFound(w, r)
		}
	})
}

