// ArchiveClient is a client for the elephant.distribution.Archive service.
type ArchiveClient interface {
	// ListArchivedDocuments enumerates the latest archived version of every
	// document offloaded to the archive, for a current-state snapshot. Pair
	// it with a Content.GetNewDocuments tail from watermark_event_id to
	// reconstruct full current state.
	ListArchivedDocuments(context.Context, *connect.Request[distribution.ListArchivedDocumentsRequest]) (*connect.Response[distribution.ListArchivedDocumentsResponse], error)
	// ListArchiveChunks lists archived eventlog chunks in order, for full
	// ordered replay of the history that precedes the hot log.
	ListArchiveChunks(context.Context, *connect.Request[distribution.ListArchiveChunksRequest]) (*connect.Response[distribution.ListArchiveChunksResponse], error)
	// GetArchivedDocument returns a fresh presigned URL for a specific
	// archived document version. Used to resolve replay bodies and to
	// re-mint a URL a consumer let expire.
	GetArchivedDocument(context.Context, *connect.Request[distribution.GetArchivedDocumentRequest]) (*connect.Response[distribution.GetArchivedDocumentResponse], error)
}

